1	/**
2	 * How the map is handed to the automatic layout engine, and how its answer is
3	 * read back.
4	 *
5	 * Everything here is a plain function over plain data: no browser, no worker,
6	 * no React. That is on purpose — it is the part worth testing, and it is
7	 * testable without starting anything.
8	 *
9	 * The layout engine is ELK, which sorts a map into left-to-right layers and
10	 * places the tiles in each layer so that as few arrows cross as possible. It is
11	 * slow enough on a large map to be worth keeping off the thread that draws the
12	 * page, which is what `layoutRunner.ts` does with the functions below.
13	 */
14	
15	import type { ElkExtendedEdge, ElkNode, LayoutOptions } from "elkjs/lib/elk-api";
16	import { TILE_WIDTH } from "./geometry";
17	
18	/** Where a tile sits, in the map's own coordinates. */
19	export interface Position {
20	  readonly x: number;
21	  readonly y: number;
22	}
23	
24	/**
25	 * Where a tile sits, and how tall it was when it was put there.
26	 *
27	 * The height is kept beside the place because a pin is only ever good for the
28	 * boxes it was made with. See `pinsFor`.
29	 */
30	export interface PinnedTile {
31	  /** Where it was put. */
32	  readonly at: Position;
33	  /** How tall it was when it was put there. */
34	  readonly height: number;
35	}
36	
37	/**
38	 * The pins to hand the layout engine — all of them, or none.
39	 *
40	 * **A pin is only good for the boxes it was made with.** Pinning exists for a
41	 * map that *grows*: a claim arriving must not shove the claims already drawn, so
42	 * every tile that has a place keeps it to the pixel. A tile that **changes
43	 * size** is a different question with a different answer, and holding a grown
44	 * tile where its shorter self went runs it into whatever sits below.
45	 *
46	 * It has to be all or none, and the reason is worth writing down: a tile's place
47	 * in a column is decided by its neighbours as much as by itself. Drop one tile's
48	 * pin and keep its neighbour's, and the engine places the unpinned one freely
49	 * while we force the pinned one back to a coordinate worked out for a map that
50	 * no longer exists — and the two meet in the middle. So the moment any box is a
51	 * different size from the one it was placed at, **every** pin goes and the map is
52	 * laid out again from scratch.
53	 *
54	 * That costs nothing the reader can see. The layout is a pure function of the
55	 * map, so the answer is the same every time; columns cannot slide, because which
56	 * column a tile is in is decided by the arrows and never by a height; and the
57	 * reader's place is kept by the view centring on whatever the keyboard is on,
58	 * which is what `layout-and-zoom.md` asks for and what the canvas already does.
59	 *
60	 * @param placed Where tiles sat after the last layout, with the heights they
61	 *   were placed at.
62	 * @param tiles Every tile to place now, with the height it will be drawn at.
63	 */
64	export function pinsFor(
65	  placed: ReadonlyMap<string, PinnedTile>,
66	  tiles: readonly LayoutTile[],
67	): Map<string, Position> {
68	  const resized = tiles.some((tile) => {
69	    const pin = placed.get(tile.id);
70	    return pin !== undefined && pin.height !== tile.height;
71	  });
72	  if (resized) {
73	    return new Map();
74	  }
75	  const holding = new Map<string, Position>();
76	  for (const tile of tiles) {
77	    const pin = placed.get(tile.id);
78	    if (pin !== undefined) {
79	      holding.set(tile.id, pin.at);
80	    }
81	  }
82	  return holding;
83	}
84	
85	/**
86	 * One tile, reduced to the two things the layout engine needs: what it is
87	 * called and how tall it is.
88	 *
89	 * The height comes from the claim's own content — see `geometry.ts` — rather
90	 * than from measuring a tile the browser has drawn. That is what keeps the
91	 * layout a plain function of the map, testable without a browser, and it is why
92	 * a tile's box and the box the layout reserved for it are always the same box.
93	 */
94	export interface LayoutTile {
95	  readonly id: string;
96	  readonly height: number;
97	}
98	
99	/** One arrow, reduced to the two things the layout engine needs. */
100	export interface LayoutEdge {
101	  readonly id: string;
102	  readonly source: string;
103	  readonly target: string;
104	}
105	
106	/**
107	 * The layout settings, written out in one place so the picture can be argued
108	 * with rather than guessed at.
109	 *
110	 * - **layered** — claims are sorted into columns and arrows travel between
111	 *   them. This is what makes the map readable left to right instead of a ball
112	 *   of string.
113	 * - **RIGHT** — causes on the left, effects on the right, which is the order an
114	 *   English sentence puts them in.
115	 * - **NETWORK_SIMPLEX** — how tiles are placed up and down within a column. It
116	 *   pulls each tile level with the tiles it is joined to, so an arrow is
117	 *   horizontal wherever it can be.
118	 * - **semiInteractive** — when a tile already has a position, keep its place in
119	 *   the order of its column rather than sorting it afresh. This is what stops
120	 *   the map rearranging itself as it grows.
121	 * - **120 between layers** — the gap between columns, which is also the length
122	 *   of the shortest wire, and so how much room a wire has to say something.
123	 * - **48 within a layer** — the gap between two tiles in the same column. Not
124	 *   settled anywhere; chosen so the note a tile opens when you look at a belief
125	 *   chip has somewhere to go.
126	 */
127	export const LAYOUT_OPTIONS: LayoutOptions = {
128	  "elk.algorithm": "layered",
129	  "elk.direction": "RIGHT",
130	  "elk.layered.nodePlacement.strategy": "NETWORK_SIMPLEX",
131	  "elk.layered.crossingMinimization.semiInteractive": "true",
132	  "elk.layered.spacing.nodeNodeBetweenLayers": "120",
133	  "elk.spacing.nodeNode": "48",
134	};
135	
136	/**
137	 * Build the map the layout engine is asked to lay out.
138	 *
139	 * Tiles that already have a position are handed back with it, as a hint that
140	 * says "this one is already somewhere; work around it". That, together with the
141	 * semi-interactive setting above, is what keeps a tile arriving late from
142	 * shuffling the tiles that arrived before it.
143	 *
144	 * @param tiles Every tile to place, with its height, in reading order.
145	 * @param edges Every arrow between them. Feedback arrows are left out by the
146	 *   caller: an arrow that points backwards has no say in a left-to-right order.
147	 * @param placed Where tiles already sit, for the ones that have been placed.
148	 */
149	export function toElkGraph(
150	  tiles: readonly LayoutTile[],
151	  edges: readonly LayoutEdge[],
152	  placed: ReadonlyMap<string, Position>,
153	): ElkNode {
154	  const children: ElkNode[] = tiles.map(({ id, height }) => {
155	    const already = placed.get(id);
156	    const child: ElkNode = { id, width: TILE_WIDTH, height };
157	    if (already !== undefined) {
158	      return {
159	        ...child,
160	        x: already.x,
161	        y: already.y,
162	        layoutOptions: { "elk.position": `(${already.x},${already.y})` },
163	      };
164	    }
165	    return child;
166	  });
167	
168	  const wires: ElkExtendedEdge[] = edges.map((edge) => ({
169	    id: edge.id,
170	    sources: [edge.source],
171	    targets: [edge.target],
172	  }));
173	
174	  return { id: "map", layoutOptions: LAYOUT_OPTIONS, children, edges: wires };
175	}
176	
177	/**
178	 * The gap the layout leaves between two boxes in one column.
179	 *
180	 * The same forty-eight pixels `LAYOUT_OPTIONS` asks the engine for, written here
181	 * as a number because the rule below has to leave it too, and one gap written in
182	 * two places is two gaps waiting to disagree.
183	 */
184	export const COLUMN_GAP = Number(LAYOUT_OPTIONS["elk.spacing.nodeNode"]);
185	
186	/** Do these two boxes stand in the same column? */
187	function sameColumn(one: Placed, other: Placed): boolean {
188	  return Math.abs(one.at.x - other.at.x) < TILE_WIDTH;
189	}
190	
191	/** Do these two boxes overlap, or touch, once the column's gap is counted? */
192	function runsInto(one: Placed, other: Placed): boolean {
193	  return (
194	    sameColumn(one, other) &&
195	    one.at.y < other.at.y + other.height + COLUMN_GAP &&
196	    other.at.y < one.at.y + one.height + COLUMN_GAP
197	  );
198	}
199	
200	/** One box, where it is and how tall it is. */
201	interface Placed {
202	  readonly id: string;
203	  readonly at: Position;
204	  readonly height: number;
205	}
206	
207	/**
208	 * Read the layout engine's answer back, keeping every tile that was already
209	 * placed exactly where it was — and making a tile that has just arrived find a
210	 * gap rather than land on one of them.
211	 *
212	 * The hint in `toElkGraph` asks the engine to leave placed tiles alone, and it
213	 * mostly does — but "mostly" is not a promise, and losing your place because a
214	 * new tile arrived is the thing this is here to prevent. So the rule is made
215	 * absolute on our side: **a tile that had a position keeps that position, to the
216	 * pixel, and only a tile that had none takes a new one.**
217	 *
218	 * **That half alone is not enough, and a map that builds itself is where it
219	 * shows.** `elk.position` is a hint about the *order* of a column, not a
220	 * coordinate the engine is bound by: it lays the whole map out freshly, moving
221	 * the placed tiles as it sees fit, and then we put those back where they were.
222	 * The tile that arrived keeps a coordinate worked out for an arrangement that no
223	 * longer exists — and the two meet in the middle, which on the Hormuz run put
224	 * one claim exactly on top of another.
225	 *
226	 * So the arriving tiles are settled afterwards, in the order the engine proposed
227	 * them: each keeps its column, starts where the engine put it, and slides **down**
228	 * until it clears every box already settled by the column's own gap. Nothing that
229	 * was already placed moves a pixel; the late arrival finds a gap, which is what
230	 * the chapter says happens and what nothing was making happen.
231	 *
232	 * Reserved rectangles are boxes here like any other. A claim drawn on top of the
233	 * rectangle that was held open for it is the same mistake as two claims on top of
234	 * each other.
235	 *
236	 * @param laidOut What the layout engine returned.
237	 * @param placed Where tiles already sat before it ran.
238	 * @returns Where every tile sits now.
239	 */
240	export function readPositions(
241	  laidOut: ElkNode,
242	  placed: ReadonlyMap<string, Position>,
243	): Map<string, Position> {
244	  const settled: Placed[] = [];
245	  const arriving: Placed[] = [];
246	
247	  for (const child of laidOut.children ?? []) {
248	    const height = child.height ?? 0;
249	    const pinned = placed.get(child.id);
250	    if (pinned !== undefined) {
251	      settled.push({ id: child.id, at: pinned, height });
252	    } else {
253	      arriving.push({ id: child.id, at: { x: child.x ?? 0, y: child.y ?? 0 }, height });
254	    }
255	  }
256	
257	  // The engine's own order, so the same map always settles the same way. The
258	  // identifier breaks a tie, because two boxes proposed at the same height must
259	  // not depend on which the engine happened to list first.
260	  arriving.sort((one, other) => one.at.y - other.at.y || one.id.localeCompare(other.id));
261	
262	  for (const box of arriving) {
263	    let at = box.at;
264	    // Each pass can only push the box further down, and there are finitely many
265	    // boxes below it, so this always settles.
266	    for (let pass = 0; pass <= settled.length; pass += 1) {
267	      const inTheWay = settled.find((other) => runsInto({ ...box, at }, other));
268	      if (inTheWay === undefined) {
269	        break;
270	      }
271	      at = { x: at.x, y: inTheWay.at.y + inTheWay.height + COLUMN_GAP };
272	    }
273	    settled.push({ ...box, at });
274	  }
275	
276	  return new Map(settled.map((box) => [box.id, box.at]));
277	}
