1	/**
2	 * Sorting a map into left-to-right layers, and capping how wide a layer gets.
3	 *
4	 * Two jobs, both of them about shape and neither about numbers. Nothing in this
5	 * file reads a likelihood, a strength or a date: it follows arrows, which is
6	 * counting steps, not arithmetic.
7	 *
8	 * **Why we work out the layers ourselves when the layout engine does it too.**
9	 * The cap — seven tiles across, then a "+n more" tile — has to be applied
10	 * before the layout engine is asked to place anything, or it would lay out
11	 * tiles it is about to be told to forget. So the layering is computed here,
12	 * used to decide what is shown, and the layout engine is handed the survivors.
13	 *
14	 * **Feedback arrows are set aside first.** A map is a left-to-right ordering of
15	 * claims, which needs there to be no loops in it. The one arrow allowed to
16	 * close a loop is a market feeding back on the world, and it is marked as such
17	 * on the map itself. Set it aside and an ordering exists again; the arrow is
18	 * still drawn, it just does not get a vote on who comes first.
19	 */
20	
21	import type { LinkView } from "../world";
22	import { TILES_PER_LAYER } from "./geometry";
23	
24	/** One claim placed in a layer. */
25	export interface Placed {
26	  /** The claim's identifier. */
27	  readonly id: string;
28	  /** Which layer it sits in, counting from zero on the left. */
29	  readonly layer: number;
30	}
31	
32	/** A layer that had more tiles in it than it is allowed to show. */
33	export interface Overflow {
34	  /** Which layer overflowed. */
35	  readonly layer: number;
36	  /** How many tiles are not shown. */
37	  readonly count: number;
38	  /** The claims that are not shown, so nothing has been silently dropped. */
39	  readonly hidden: readonly string[];
40	}
41	
42	/** What a map looks like once it has been sorted and capped. */
43	export interface Layered {
44	  /** The claims that are shown, each with its layer. */
45	  readonly shown: readonly Placed[];
46	  /** One entry for each layer that had to collapse some tiles. */
47	  readonly overflows: readonly Overflow[];
48	}
49	
50	/**
51	 * Put every claim in a layer: as far right as the longest chain of arrows
52	 * reaching it.
53	 *
54	 * A claim with nothing pointing at it sits in layer zero. Every other claim
55	 * sits one layer to the right of the furthest-right claim that points at it, so
56	 * an arrow always travels left to right and a chain of three arrows is three
57	 * layers long. This is the reading order of the map, and it is why the map is
58	 * never a hairball: the picture has a direction.
59	 *
60	 * @param ids Every claim on the map, in the order the map serves them.
61	 * @param links Every arrow on the map, feedback arrows included — they are set
62	 *   aside here rather than by the caller.
63	 * @returns Each claim's layer, in the same order the claims came in.
64	 */
65	export function assignLayers(ids: readonly string[], links: readonly LinkView[]): Placed[] {
66	  const present = new Set(ids);
67	  // Feedback arrows are set aside: they are the ones allowed to point backwards,
68	  // and a backwards arrow has no place in deciding what comes first.
69	  const forward = links.filter(
70	    (link) => !link.reflexive && present.has(link.source) && present.has(link.target),
71	  );
72	
73	  const causes = new Map<string, string[]>();
74	  for (const id of ids) {
75	    causes.set(id, []);
76	  }
77	  for (const link of forward) {
78	    causes.get(link.target)?.push(link.source);
79	  }
80	
81	  const layer = new Map<string, number>();
82	  // Depth-first, remembering answers, with a guard against the loop that should
83	  // not be there. If a loop survived the feedback filter — a map that broke its
84	  // own rules — the claim lands in layer zero rather than hanging the browser.
85	  const inProgress = new Set<string>();
86	  const layerOf = (id: string): number => {
87	    const known = layer.get(id);
88	    if (known !== undefined) {
89	      return known;
90	    }
91	    if (inProgress.has(id)) {
92	      return 0;
93	    }
94	    inProgress.add(id);
95	    let furthest = -1;
96	    for (const cause of causes.get(id) ?? []) {
97	      furthest = Math.max(furthest, layerOf(cause));
98	    }
99	    inProgress.delete(id);
100	    const answer = furthest + 1;
101	    layer.set(id, answer);
102	    return answer;
103	  };
104	
105	  return ids.map((id) => ({ id, layer: layerOf(id) }));
106	}
107	
108	/**
109	 * Show at most seven tiles in a layer and collapse the rest into one.
110	 *
111	 * Seven is a cap on how wide the map gets, not a judgement about which claims
112	 * matter: the tiles kept are the first seven in the order the map served them,
113	 * and the ones that are not shown are named in the overflow so the collapsed
114	 * tile can say exactly what it is standing in for. A map that quietly dropped
115	 * claims would be lying about its own shape.
116	 *
117	 * @param placed Every claim with its layer, from `assignLayers`.
118	 * @returns What is shown, and one overflow entry per layer that had too many.
119	 */
120	export function capLayers(placed: readonly Placed[]): Layered {
121	  const byLayer = new Map<number, Placed[]>();
122	  for (const one of placed) {
123	    const existing = byLayer.get(one.layer);
124	    if (existing === undefined) {
125	      byLayer.set(one.layer, [one]);
126	    } else {
127	      existing.push(one);
128	    }
129	  }
130	
131	  const shown: Placed[] = [];
132	  const overflows: Overflow[] = [];
