/**
 * How a real Hormuz map comes out when it is laid out the way the screen lays it
 * out — one claim at a time, with everything already placed pinned — against how
 * it comes out when the whole finished map is laid out once.
 *
 * Nothing here reimplements the app. The layering, the pinning, the ELK options
 * and the tile heights are imported from `frontend/src/graph/` through the
 * bundle `run.sh` builds. The only code written here is the replay of a stream
 * and the counting of what came out.
 *
 * Run it with `run.sh`, which builds that bundle first.
 */

import { readFileSync } from "node:fs";
import { argv } from "node:process";

const REPO = "/Users/kentgang/git3/katalyst";
const BUNDLE = argv[2];

const app = await import(BUNDLE);
const elkModule = await import(`${REPO}/frontend/node_modules/elkjs/lib/elk.bundled.js`);
const ELK = elkModule.default ?? elkModule;

const {
  LAYOUT_OPTIONS,
  pinsFor,
  readPositions,
  toElkGraph,
  assignLayers,
  capLayers,
  TILE_MIN_HEIGHT,
  TILE_WIDTH,
  tileHeight,
  firstFrame,
} = app;

const TILES_PER_LAYER = 7;
const PORT_STANDOFF = 8;
const DOWN_THE_TILE = { trigger: 0.38, sustain: 0.62 };

/* ---- reading the two kinds of file the repository keeps ----------------- */

/** The events of a committed recording, in the order they went on the wire. */
function eventsOfARecording(path) {
  const lines = readFileSync(path, "utf8").split("\n").filter((line) => line.trim() !== "");
  const events = [];
  for (const line of lines) {
    const parsed = JSON.parse(line);
    if (parsed.event === undefined) {
      continue; // the header line
    }
    events.push({ event: parsed.event, ...parsed.data });
  }
  return events;
}

/**
 * The events of a kept run. The file stores each event's payload without its
 * name, so the name is read back off the fields only that event has.
 */
function eventsOfAKeptRun(path) {
  const run = JSON.parse(readFileSync(path, "utf8"));
  return run.events.map((payload) => {
    if ("generation_id" in payload && "hypothesis" in payload) {
      return { event: "generation_started", ...payload };
    }
    if ("proposition" in payload) {
      return { event: "proposal_accepted", ...payload };
    }
    if ("claim_in_words" in payload) {
      return { event: "proposal_rejected", ...payload };
    }
    if ("world" in payload) {
      return { event: "beliefs_propagated", ...payload };
    }
    if ("path" in payload) {
      return { event: "verdict", ...payload };
    }
    if ("dollars" in payload) {
      return { event: "receipt", ...payload };
    }
    if ("reason" in payload) {
      return { event: "done", ...payload };
    }
    return { event: "unknown", ...payload };
  });
}

/* ---- the browser's own view of a claim, as far as a height needs it ----- */

/**
 * The claim a tile draws, built from the proposal the way
 * `frontend/src/world/fromTheServer.ts` builds it — only the fields
 * `geometry.ts` reads to work out a height.
 */
function growingClaim(proposition) {
  return {
    id: proposition.id,
    claim: proposition.claim,
    kind: proposition.kind,
    beliefs: {
      model: { absence: { code: "while_it_grows" } },
      user: { absence: { code: "not_said" } },
      market: proposition.beliefs?.market
        ? { p: proposition.beliefs.market.p }
        : { absence: { code: "not_quoted" } },
    },
    evidence: (proposition.evidence ?? []).slice(0, 2),
    badges: [],
  };
}

/* ---- what `toFlow` hands the layout ------------------------------------- */

function whatTheLayoutSees(claims, links, skeletons) {
  const ids = claims.map((claim) => claim.id);
  const { shown, overflows } = capLayers(assignLayers(ids, links));
  const drawn = new Set(shown.map((one) => one.id));
  const byId = new Map(claims.map((claim) => [claim.id, claim]));

  const tiles = [];
  for (const placed of shown) {
    const claim = byId.get(placed.id);
    tiles.push({ id: claim.id, height: tileHeight(claim) });
  }
  for (const overflow of overflows) {
    tiles.push({ id: `more-in-column-${overflow.layer}`, height: TILE_MIN_HEIGHT });
  }

  const edges = links
    .filter((link) => !link.reflexive && drawn.has(link.source) && drawn.has(link.target))
    .map((link) => ({ id: link.id, source: link.source, target: link.target }));

  for (const overflow of overflows) {
    const hidden = new Set(overflow.hidden);
    const causes = new Set(
      links
        .filter((link) => !link.reflexive && hidden.has(link.target) && drawn.has(link.source))
        .map((link) => link.source),
    );
    for (const cause of causes) {
      edges.push({
        id: `standing-in:${cause}->more-in-column-${overflow.layer}`,
        source: cause,
        target: `more-in-column-${overflow.layer}`,
      });
    }
  }

  for (const box of skeletons) {
    tiles.push({ id: box.id, height: TILE_MIN_HEIGHT });
    if (box.after !== null && drawn.has(box.after)) {
      edges.push({ id: `holding-open:${box.after}->${box.id}`, source: box.after, target: box.id });
    }
  }

  return { tiles, edges, drawn };
}

/* ---- the two ways of laying a map out ----------------------------------- */

const elk = new ELK();

/** One layout pass, exactly as `useLayout` runs one. */
async function onePass(tiles, edges, placed) {
  const holding = pinsFor(placed, tiles);
  const droppedEveryPin = placed.size > 0 && holding.size === 0;
  const answer = await elk.layout(toElkGraph(tiles, edges, holding));
  const positions = readPositions(answer, holding);
  const heights = new Map(tiles.map((tile) => [tile.id, tile.height]));
  const next = new Map(
    [...positions].map(([id, at]) => [id, { at, height: heights.get(id) ?? 0 }]),
  );
  return { positions, placed: next, droppedEveryPin };
}

/** The screen's way: fold each event in, lay out again, keep every pin. */
async function incrementalWithPinning(events) {
  let claims = [];
  let links = [];
  let skeletons = [];
  let placed = new Map();
  let positions = new Map();
  let passes = 0;
  let pinDrops = 0;

  for (const event of events) {
    if (event.event === "generation_started") {
      skeletons = [{ id: "skeleton:hypothesis", words: event.hypothesis, after: null }];
    } else if (event.event === "proposal_accepted") {
      if (event.proposition !== null && event.proposition !== undefined) {
        claims = [...claims, growingClaim(event.proposition)];
      }
      const there = new Set(claims.map((claim) => claim.id));
      links = [
        ...links,
        ...(event.links ?? []).filter((link) => there.has(link.source) && there.has(link.target)),
      ];
      skeletons = (event.frontier ?? []).map((id) => ({ id: `skeleton:${id}`, after: id }));
    } else if (event.event === "proposal_rejected") {
      skeletons = (event.frontier ?? []).map((id) => ({ id: `skeleton:${id}`, after: id }));
    } else if (event.event === "beliefs_propagated" || event.event === "done") {
      skeletons = [];
    } else {
      continue;
    }
    const { tiles, edges } = whatTheLayoutSees(claims, links, skeletons);
    if (tiles.length === 0) {
      continue;
    }
    const pass = await onePass(tiles, edges, placed);
    placed = pass.placed;
    positions = pass.positions;
    passes += 1;
    if (pass.droppedEveryPin) {
      pinDrops += 1;
    }
  }
  return { claims, links, positions, passes, pinDrops };
}

/** The other way: the finished map, laid out once, with nothing pinned. */
async function oneWholeLayout(claims, links, options) {
  const { tiles, edges } = whatTheLayoutSees(claims, links, []);
  const graph = toElkGraph(tiles, edges, new Map());
  if (options !== undefined) {
    graph.layoutOptions = { ...LAYOUT_OPTIONS, ...options };
  }
  const answer = await elk.layout(graph);
  return readPositions(answer, new Map());
}

/* ---- counting what came out --------------------------------------------- */

function attachPoints(positions, heights, link) {
  const from = positions.get(link.source);
  const to = positions.get(link.target);
  if (from === undefined || to === undefined) {
    return null;
  }
  const share = DOWN_THE_TILE[link.mode === "sustain" ? "sustain" : "trigger"];
  return {
    a: {
      x: from.x + TILE_WIDTH + PORT_STANDOFF,
      y: from.y + (heights.get(link.source) ?? 0) * share,
    },
    b: { x: to.x - PORT_STANDOFF, y: to.y + (heights.get(link.target) ?? 0) * share },
  };
}

function side(p, q, r) {
  return Math.sign((q.x - p.x) * (r.y - p.y) - (q.y - p.y) * (r.x - p.x));
}

function cross(one, other) {
  const d1 = side(one.a, one.b, other.a);
  const d2 = side(one.a, one.b, other.b);
  const d3 = side(other.a, other.b, one.a);
  const d4 = side(other.a, other.b, one.b);
  return d1 !== d2 && d3 !== d4 && d1 !== 0 && d2 !== 0 && d3 !== 0 && d4 !== 0;
}

function score(claims, links, positions) {
  const heights = new Map(claims.map((claim) => [claim.id, tileHeight(claim)]));
  const drawn = links.filter(
    (link) => positions.has(link.source) && positions.has(link.target),
  );

  let backwards = 0;
  let sameColumn = 0;
  let noForwardRoom = 0;
  let feedbackBackwards = 0;
  let length = 0;
  const segments = [];

  for (const link of drawn) {
    const from = positions.get(link.source);
    const to = positions.get(link.target);
    const points = attachPoints(positions, heights, link);
    if (points !== null) {
      segments.push(points);
      length += Math.hypot(points.b.x - points.a.x, points.b.y - points.a.y);
    }
    if (link.reflexive) {
      if (to.x <= from.x) {
        feedbackBackwards += 1;
      }
      continue;
    }
    if (to.x < from.x) {
      backwards += 1;
    } else if (to.x === from.x) {
      sameColumn += 1;
    }
    if (to.x < from.x + TILE_WIDTH) {
      noForwardRoom += 1;
    }
  }

  let crossings = 0;
  for (let i = 0; i < segments.length; i += 1) {
    for (let j = i + 1; j < segments.length; j += 1) {
      if (cross(segments[i], segments[j])) {
        crossings += 1;
      }
    }
  }

  const boxes = [...positions].filter(([id]) => heights.has(id));
  const left = Math.min(...boxes.map(([, at]) => at.x));
  const top = Math.min(...boxes.map(([, at]) => at.y));
  const right = Math.max(...boxes.map(([, at]) => at.x + TILE_WIDTH));
  const bottom = Math.max(...boxes.map(([id, at]) => at.y + (heights.get(id) ?? 0)));
  const columns = new Set(boxes.map(([, at]) => Math.round(at.x))).size;

  // The stage the spec measured against: 1600 x 1000 less the panel and the
  // strips, which `streaming-growth.md` open question 2 gives as 1264 x 801.
  const stage = { width: 1264, height: 801 };
  const map = { x: left, y: top, width: right - left, height: bottom - top };
  const frame = firstFrame(map, stage);
  const whollyOnTheGlass = boxes.filter(([id, at]) => {
    const x0 = at.x * frame.zoom + frame.x;
    const y0 = at.y * frame.zoom + frame.y;
    const x1 = (at.x + TILE_WIDTH) * frame.zoom + frame.x;
    const y1 = (at.y + (heights.get(id) ?? 0)) * frame.zoom + frame.y;
    return x0 >= 0 && y0 >= 0 && x1 <= stage.width && y1 <= stage.height;
  }).length;

  return {
    tiles: boxes.length,
    arrows: drawn.length,
    columns,
    backwards,
    sameColumn,
    noForwardRoom,
    feedbackBackwards,
    crossings,
    length: Math.round(length),
    width: Math.round(map.width),
    height: Math.round(map.height),
    zoom: Number(frame.zoom.toFixed(2)),
    whollyOnTheGlass,
  };
}

/* ---- the table ----------------------------------------------------------- */

const maps = [
  {
    name: "the committed recording  backend/recordings/hormuz.jsonl",
    events: eventsOfARecording(`${REPO}/backend/recordings/hormuz.jsonl`),
  },
  {
    name: "kept live run  18-24-54Z (Verify door, 6 claims)",
    events: eventsOfAKeptRun(
      `${REPO}/backend/.runs/hormuz-2026-09-21T18-24-54Z-01M32HVA1F3SX18H513M6GTNPT.json`,
    ),
  },
  {
    name: "kept live run  18-31-02Z (Verify door, 4 claims)",
    events: eventsOfAKeptRun(
      `${REPO}/backend/.runs/hormuz-2026-09-21T18-31-02Z-01M32K42Z4036436TG96Q46RN0.json`,
    ),
  },
];

const columns = [
  ["tiles", 5],
  ["arrows", 6],
  ["columns", 7],
  ["backwards", 9],
  ["sameColumn", 10],
  ["noForwardRoom", 13],
  ["crossings", 9],
  ["length", 7],
  ["width", 6],
  ["height", 6],
  ["zoom", 5],
  ["whollyOnTheGlass", 16],
];

function row(label, scored) {
  const cells = columns.map(([key, width]) => String(scored[key]).padStart(width));
  return `${label.padEnd(34)}${cells.join(" ")}`;
}

console.log(
  `${"".padEnd(34)}${columns.map(([key, width]) => key.padStart(width)).join(" ")}`,
);
console.log("-".repeat(34 + columns.reduce((sum, [, width]) => sum + width + 1, 0)));

for (const map of maps) {
  const incremental = await incrementalWithPinning(map.events);
  const whole = await oneWholeLayout(incremental.claims, incremental.links);
  const withCycleBreaking = await oneWholeLayout(incremental.claims, incremental.links, {
    "elk.layered.crossingMinimization.semiInteractive": "false",
  });

  console.log(`\n${map.name}`);
  console.log(
    `  ${incremental.passes} layout passes, ${incremental.pinDrops} of them with every pin dropped`,
  );
  console.log(row("  incremental, with pinning", score(incremental.claims, incremental.links, incremental.positions)));
  console.log(row("  one whole layout", score(incremental.claims, incremental.links, whole)));
  console.log(
    row(
      "  one whole layout, no semiInter.",
      score(incremental.claims, incremental.links, withCycleBreaking),
    ),
  );

  // How far a tile would move if the map settled at the end of the run.
  let moved = 0;
  let furthest = 0;
  for (const [id, at] of incremental.positions) {
    const then = whole.get(id);
    if (then === undefined) {
      continue;
    }
    const distance = Math.hypot(then.x - at.x, then.y - at.y);
    if (distance > 0.5) {
      moved += 1;
    }
    furthest = Math.max(furthest, distance);
  }
  console.log(
    `  a settle would move ${moved} of ${incremental.positions.size} tiles, the furthest by ${Math.round(furthest)} px`,
  );
}

