 * out — one claim at a time, with everything already placed pinned — against how
 * it comes out when the whole finished map is laid out once.
 *
 * Nothing here reimplements the app. The layering, the pinning, the ELK options
 * and the tile heights are imported from `frontend/src/graph/` through the
 * bundle `run.sh` builds. The only code written here is the replay of a stream
 * and the counting of what came out.
 *
 * Run it with `run.sh`, which builds that bundle first.
 */

import { readFileSync } from "node:fs";
import { argv } from "node:process";

const REPO = "/Users/kentgang/git3/katalyst";
const BUNDLE = argv[2];

const app = await import(BUNDLE);
const elkModule = await import(`${REPO}/frontend/node_modules/elkjs/lib/elk.bundled.js`);
const ELK = elkModule.default ?? elkModule;

const {
  LAYOUT_OPTIONS,
  pinsFor,
  readPositions,
