async function incrementalWithPinning(events) {
  let claims = [];
  let links = [];
  let skeletons = [];
  let placed = new Map();
  let positions = new Map();
  let passes = 0;
  let pinDrops = 0;

  for (const event of events) {
    if (event.event === "generation_started") {
      skeletons = [{ id: "skeleton:hypothesis", words: event.hypothesis, after: null }];
    } else if (event.event === "proposal_accepted") {
      if (event.proposition !== null && event.proposition !== undefined) {
        claims = [...claims, growingClaim(event.proposition)];
