      const there = new Set(claims.map((claim) => claim.id));
      links = [
        ...links,
        ...(event.links ?? []).filter((link) => there.has(link.source) && there.has(link.target)),
      ];
      skeletons = (event.frontier ?? []).map((id) => ({ id: `skeleton:${id}`, after: id }));
    } else if (event.event === "proposal_rejected") {
      skeletons = (event.frontier ?? []).map((id) => ({ id: `skeleton:${id}`, after: id }));
    } else if (event.event === "beliefs_propagated" || event.event === "done") {
      skeletons = [];
    } else {
      continue;
    }
    const { tiles, edges } = whatTheLayoutSees(claims, links, skeletons);
    if (tiles.length === 0) {
      continue;
    }
    const pass = await onePass(tiles, edges, placed);
    placed = pass.placed;
    positions = pass.positions;
    passes += 1;
    if (pass.droppedEveryPin) {
      pinDrops += 1;
    }
  }
