}

/* ---- counting what came out --------------------------------------------- */

function attachPoints(positions, heights, link) {
  const from = positions.get(link.source);
  const to = positions.get(link.target);
  if (from === undefined || to === undefined) {
    return null;
  }
  const share = DOWN_THE_TILE[link.mode === "sustain" ? "sustain" : "trigger"];
  return {
    a: {
      x: from.x + TILE_WIDTH + PORT_STANDOFF,
      y: from.y + (heights.get(link.source) ?? 0) * share,
    },
    b: { x: to.x - PORT_STANDOFF, y: to.y + (heights.get(link.target) ?? 0) * share },
  };
}

function side(p, q, r) {
  return Math.sign((q.x - p.x) * (r.y - p.y) - (q.y - p.y) * (r.x - p.x));
}

function cross(one, other) {
  const d1 = side(one.a, one.b, other.a);
  const d2 = side(one.a, one.b, other.b);
  const d3 = side(other.a, other.b, one.a);
  const d4 = side(other.a, other.b, one.b);
  return d1 !== d2 && d3 !== d4 && d1 !== 0 && d2 !== 0 && d3 !== 0 && d4 !== 0;
}

function score(claims, links, positions) {
  const heights = new Map(claims.map((claim) => [claim.id, tileHeight(claim)]));
  const drawn = links.filter(
    (link) => positions.has(link.source) && positions.has(link.target),
  );

  let backwards = 0;
  let sameColumn = 0;
  let noForwardRoom = 0;
  let feedbackBackwards = 0;
  let length = 0;
  const segments = [];

  for (const link of drawn) {
    const from = positions.get(link.source);
    const to = positions.get(link.target);
    const points = attachPoints(positions, heights, link);
    if (points !== null) {
      segments.push(points);
      length += Math.hypot(points.b.x - points.a.x, points.b.y - points.a.y);
    }
    if (link.reflexive) {
      if (to.x <= from.x) {
        feedbackBackwards += 1;
      }
      continue;
    }
    if (to.x < from.x) {
      backwards += 1;
    } else if (to.x === from.x) {
      sameColumn += 1;
    }
    if (to.x < from.x + TILE_WIDTH) {
      noForwardRoom += 1;
    }
  }

  let crossings = 0;
  for (let i = 0; i < segments.length; i += 1) {
    for (let j = i + 1; j < segments.length; j += 1) {
      if (cross(segments[i], segments[j])) {
        crossings += 1;
      }
    }
  }

  const boxes = [...positions].filter(([id]) => heights.has(id));
  const left = Math.min(...boxes.map(([, at]) => at.x));
  const top = Math.min(...boxes.map(([, at]) => at.y));
  const right = Math.max(...boxes.map(([, at]) => at.x + TILE_WIDTH));
  const bottom = Math.max(...boxes.map(([id, at]) => at.y + (heights.get(id) ?? 0)));
