const maps = [
  {
    name: "the committed recording  backend/recordings/hormuz.jsonl",
    events: eventsOfARecording(`${REPO}/backend/recordings/hormuz.jsonl`),
  },
  {
    name: "kept live run  18-24-54Z (Verify door, 6 claims)",
    events: eventsOfAKeptRun(
      `${REPO}/backend/.runs/hormuz-2026-09-21T18-24-54Z-01M32HVA1F3SX18H513M6GTNPT.json`,
    ),
  },
  {
    name: "kept live run  18-31-02Z (Verify door, 4 claims)",
    events: eventsOfAKeptRun(
      `${REPO}/backend/.runs/hormuz-2026-09-21T18-31-02Z-01M32K42Z4036436TG96Q46RN0.json`,
    ),
  },
];

const columns = [
  ["tiles", 5],
  ["arrows", 6],
  ["columns", 7],
  ["backwards", 9],
  ["sameColumn", 10],
  ["noForwardRoom", 13],
  ["crossings", 9],
  ["length", 7],
  ["width", 6],
  ["height", 6],
  ["zoom", 5],
  ["whollyOnTheGlass", 16],
];

function row(label, scored) {
  const cells = columns.map(([key, width]) => String(scored[key]).padStart(width));
  return `${label.padEnd(34)}${cells.join(" ")}`;
}

console.log(
  `${"".padEnd(34)}${columns.map(([key, width]) => key.padStart(width)).join(" ")}`,
);
console.log("-".repeat(34 + columns.reduce((sum, [, width]) => sum + width + 1, 0)));

for (const map of maps) {
  const incremental = await incrementalWithPinning(map.events);
  const whole = await oneWholeLayout(incremental.claims, incremental.links);
  const withCycleBreaking = await oneWholeLayout(incremental.claims, incremental.links, {
    "elk.layered.crossingMinimization.semiInteractive": "false",
  });

  console.log(`\n${map.name}`);
  console.log(
    `  ${incremental.passes} layout passes, ${incremental.pinDrops} of them with every pin dropped`,
  );
  console.log(row("  incremental, with pinning", score(incremental.claims, incremental.links, incremental.positions)));
  console.log(row("  one whole layout", score(incremental.claims, incremental.links, whole)));
  console.log(
    row(
      "  one whole layout, no semiInter.",
      score(incremental.claims, incremental.links, withCycleBreaking),
    ),
  );

  // How far a tile would move if the map settled at the end of the run.
  let moved = 0;
  let furthest = 0;
  for (const [id, at] of incremental.positions) {
    const then = whole.get(id);
    if (then === undefined) {
      continue;
    }
    const distance = Math.hypot(then.x - at.x, then.y - at.y);
    if (distance > 0.5) {
      moved += 1;
    }
    furthest = Math.max(furthest, distance);
  }
  console.log(
    `  a settle would move ${moved} of ${incremental.positions.size} tiles, the furthest by ${Math.round(furthest)} px`,
  );
}

