    if (to.x < from.x + TILE_WIDTH) {
      noForwardRoom += 1;
    }
  }

  let crossings = 0;
  for (let i = 0; i < segments.length; i += 1) {
    for (let j = i + 1; j < segments.length; j += 1) {
      if (cross(segments[i], segments[j])) {
        crossings += 1;
      }
    }
  }

  const boxes = [...positions].filter(([id]) => heights.has(id));
  const left = Math.min(...boxes.map(([, at]) => at.x));
  const top = Math.min(...boxes.map(([, at]) => at.y));
  const right = Math.max(...boxes.map(([, at]) => at.x + TILE_WIDTH));
  const bottom = Math.max(...boxes.map(([id, at]) => at.y + (heights.get(id) ?? 0)));
  const columns = new Set(boxes.map(([, at]) => Math.round(at.x))).size;

  // The stage the spec measured against: 1600 x 1000 less the panel and the
  // strips, which `streaming-growth.md` open question 2 gives as 1264 x 801.
  const stage = { width: 1264, height: 801 };
  const map = { x: left, y: top, width: right - left, height: bottom - top };
  const frame = firstFrame(map, stage);
  const whollyOnTheGlass = boxes.filter(([id, at]) => {
    const x0 = at.x * frame.zoom + frame.x;
    const y0 = at.y * frame.zoom + frame.y;
    const x1 = (at.x + TILE_WIDTH) * frame.zoom + frame.x;
    const y1 = (at.y + (heights.get(id) ?? 0)) * frame.zoom + frame.y;
