  }).length;

  return {
    tiles: boxes.length,
    arrows: drawn.length,
    columns,
    backwards,
    sameColumn,
    noForwardRoom,
    feedbackBackwards,
    crossings,
    length: Math.round(length),
    width: Math.round(map.width),
    height: Math.round(map.height),
    zoom: Number(frame.zoom.toFixed(2)),
    whollyOnTheGlass,
  };
