function eventsOfAKeptRun(path) {
  const run = JSON.parse(readFileSync(path, "utf8"));
  return run.events.map((payload) => {
    if ("generation_id" in payload && "hypothesis" in payload) return { event: "generation_started", ...payload };
    if ("proposition" in payload) return { event: "proposal_accepted", ...payload };
    if ("claim_in_words" in payload) return { event: "proposal_rejected", ...payload };
    if ("path" in payload) return { event: "verdict", ...payload };
    if ("dollars" in payload) return { event: "receipt", ...payload };
    if ("reason" in payload) return { event: "done", ...payload };
    return { event: "unknown", ...payload };
  });
}

function eventsOfARecording(path) {
  return readFileSync(path, "utf8")
    .split("\n")
    .filter((line) => line.trim() !== "")
    .map((line) => JSON.parse(line))
    .filter((parsed) => parsed.event !== undefined)
    .map((parsed) => ({ event: parsed.event, ...parsed.data }));
}

function growingClaim(proposition) {
  return {
    id: proposition.id,
    claim: proposition.claim,
    kind: proposition.kind,
    beliefs: {
      model: { absence: { code: "while_it_grows" } },
      user: { absence: { code: "not_said" } },
      market: proposition.beliefs?.market ? { p: proposition.beliefs.market.p } : { absence: { code: "not_quoted" } },
    },
    evidence: (proposition.evidence ?? []).slice(0, 2),
    badges: [],
  };
}

function whatTheLayoutSees(claims, links, skeletons) {
  const ids = claims.map((claim) => claim.id);
  const { shown, overflows } = capLayers(assignLayers(ids, links));
  const drawn = new Set(shown.map((one) => one.id));
  const byId = new Map(claims.map((claim) => [claim.id, claim]));
  const tiles = shown.map((placed) => ({ id: placed.id, height: tileHeight(byId.get(placed.id)) }));
  for (const overflow of overflows) tiles.push({ id: `more-in-column-${overflow.layer}`, height: TILE_MIN_HEIGHT });
  const edges = links
    .filter((link) => !link.reflexive && drawn.has(link.source) && drawn.has(link.target))
    .map((link) => ({ id: link.id, source: link.source, target: link.target }));
  for (const box of skeletons) {
    tiles.push({ id: box.id, height: TILE_MIN_HEIGHT });
    if (box.after !== null && drawn.has(box.after)) {
      edges.push({ id: `holding-open:${box.after}->${box.id}`, source: box.after, target: box.id });
    }
  }
  return { tiles, edges };
}

/**
 * The row-only candidate: a tile keeps the row it was put in and takes its
 * column from the layering every pass. Written here, not in the app — this is
 * a proposal being costed, not shipped code.
 */
function keepTheRowNotTheColumn(laidOut, placed, heights) {
  const boxes = (laidOut.children ?? []).map((child) => {
    const pin = placed.get(child.id);
    return {
      id: child.id,
      x: child.x ?? 0,
      y: pin === undefined ? (child.y ?? 0) : pin.at.y,
      height: heights.get(child.id) ?? 0,
      pinned: pin !== undefined,
    };
  });
  // Settle each column top to bottom so that a tile that just changed column
  // cannot land on one already there. A pinned tile keeps its row where it can.
  const settled = [];
  for (const box of [...boxes].sort((one, other) => one.x - other.x || one.y - other.y)) {
    let y = box.y;
    for (let pass = 0; pass <= settled.length; pass += 1) {
      const inTheWay = settled.find(
        (other) =>
          Math.abs(other.x - box.x) < TILE_WIDTH &&
          y < other.y + other.height + COLUMN_GAP &&
          other.y < y + box.height + COLUMN_GAP,
      );
      if (inTheWay === undefined) break;
      y = inTheWay.y + inTheWay.height + COLUMN_GAP;
    }
    settled.push({ ...box, y });
  }
  return new Map(settled.map((box) => [box.id, { x: box.x, y: box.y }]));
}

async function run(policy, events) {
  let claims = [];
  let links = [];
  let skeletons = [];
  let placed = new Map();
  let positions = new Map();
  let movedTiles = 0;
  let movedPasses = 0;
  let furthest = 0;
  let travelled = 0;

  const foldAndLayOut = async () => {
    const { tiles, edges } = whatTheLayoutSees(claims, links, skeletons);
    if (tiles.length === 0) return;
    const heights = new Map(tiles.map((tile) => [tile.id, tile.height]));
    const holding = policy === "never-pin" ? new Map() : pinsFor(placed, tiles);
    const answer = await elk.layout(toElkGraph(tiles, edges, holding));
    const next =
      policy === "row-only"
        ? keepTheRowNotTheColumn(answer, placed, heights)
        : readPositions(answer, holding);

    let movedHere = 0;
    for (const [id, at] of next) {
      const before = positions.get(id);
      if (before === undefined) continue;
      const distance = Math.hypot(at.x - before.x, at.y - before.y);
      if (distance > 0.5) {
        movedHere += 1;
        travelled += distance;
        furthest = Math.max(furthest, distance);
      }
    }
    movedTiles += movedHere;
    if (movedHere > 0) movedPasses += 1;

    positions = next;
    placed = new Map([...next].map(([id, at]) => [id, { at, height: heights.get(id) ?? 0 }]));
  };

  for (const event of events) {
    if (event.event === "generation_started") {
      skeletons = [{ id: "skeleton:hypothesis", after: null }];
    } else if (event.event === "proposal_accepted") {
      if (event.proposition) claims = [...claims, growingClaim(event.proposition)];
      const there = new Set(claims.map((claim) => claim.id));
      links = [...links, ...(event.links ?? []).filter((link) => there.has(link.source) && there.has(link.target))];
      skeletons = (event.frontier ?? []).map((id) => ({ id: `skeleton:${id}`, after: id }));
    } else if (event.event === "proposal_rejected") {
      skeletons = (event.frontier ?? []).map((id) => ({ id: `skeleton:${id}`, after: id }));
    } else if (event.event === "done") {
      skeletons = [];
    } else {
      continue;
    }
    await foldAndLayOut();
  }

  if (policy === "settle") {
    placed = new Map();
    await foldAndLayOut();
  }

  return {
    movedTiles,
    movedPasses,
    furthest: Math.round(furthest),
    travelled: Math.round(travelled),
    ...howItReads(claims, links, positions),
  };
}

/** What the finished picture reads like: arrows that double back, and how long the wire is. */
function howItReads(claims, links, positions) {
  const heights = new Map(claims.map((claim) => [claim.id, tileHeight(claim)]));
  let backwards = 0;
  let sameColumn = 0;
  let length = 0;
  let bottom = -Infinity;
  let top = Infinity;
  for (const link of links) {
    const from = positions.get(link.source);
    const to = positions.get(link.target);
    if (from === undefined || to === undefined) continue;
    if (to.x < from.x) backwards += 1;
    else if (to.x === from.x) sameColumn += 1;
    const a = { x: from.x + TILE_WIDTH + 8, y: from.y + (heights.get(link.source) ?? 0) * 0.38 };
    const b = { x: to.x - 8, y: to.y + (heights.get(link.target) ?? 0) * 0.38 };
    length += Math.hypot(b.x - a.x, b.y - a.y);
  }
  for (const [id, at] of positions) {
    if (!heights.has(id)) continue;
    top = Math.min(top, at.y);
    bottom = Math.max(bottom, at.y + (heights.get(id) ?? 0));
  }
  return { backwards, sameColumn, length: Math.round(length), tall: Math.round(bottom - top) };
}

